void filesystem_PI_init(const asn1SccT_UInt32 *IN_read_size,
			const asn1SccT_UInt32 *IN_prog_size,
			const asn1SccT_UInt32 *IN_block_size,
			const asn1SccT_UInt32 *IN_block_count,
			const asn1SccT_UInt32 *IN_block_cycles,
			const asn1SccT_UInt32 *IN_cache_size,
			const asn1SccT_UInt32 *IN_lookahead_size,
			asn1SccT_Boolean *OUT_result)
{
	cfg.read_size = *IN_read_size;
	cfg.prog_size = *IN_prog_size;
	cfg.block_size = *IN_block_size;
	cfg.block_count = *IN_block_count;
	cfg.block_cycles = *IN_block_cycles;
	cfg.cache_size = *IN_cache_size;
	cfg.lookahead_size = *IN_lookahead_size;

	if(lfs_mount(&lfs, &cfg) == 0){
		*OUT_result = true;
		return;
	}

    if (0 > lfs_format(&lfs, &cfg)) {
		FS_PRINT("[FileSystem] format error\n");
		*OUT_result = false;
		return;
	}
    if (0 > lfs_mount(&lfs, &cfg)) {
		FS_PRINT("[FileSystem] mount error\n");
		*OUT_result = false;
		return;
	}

	*OUT_result = true;
}

void filesystem_PI_file_handling_create_file(
    const asn1SccLITTLE_FS_REPOSITORY_PATH *IN_object_path,
    const asn1SccLITTLE_FS_MAXIMUM_SIZE *IN_maximum_size,
    const asn1SccLITTLE_FS_ADDITIONAL_FILE_ATTRIBUTE *IN_attributes,
    asn1SccLITTLE_FS_BOOLEAN *OUT_result)

{
	lfs_file_t file;
	uint8_t buffer[cfg.cache_size];
	memset(buffer, 0, cfg.cache_size);

	struct lfs_attr file_attr = {.type = 0,
				     .buffer = IN_attributes->field_data.arr,
				     .size = IN_attributes->field_data.nCount};

	struct lfs_file_config file_config = {
	    .buffer = buffer, .attrs = &file_attr, .attr_count = 1};

	int return_code =
	    lfs_file_opencfg(&lfs, &file, IN_object_path->field_data,
			     LFS_O_RDWR | LFS_O_CREAT, &file_config);
	if (return_code < 0) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	return_code = lfs_file_close(&lfs, &file);
	*OUT_result = return_code == 0;
}

void filesystem_PI_file_handling_delete_file(
    const asn1SccLITTLE_FS_FILE_PATH *IN_object_path,
    asn1SccLITTLE_FS_BOOLEAN *OUT_result)

{
	int return_code =
	    lfs_remove(&lfs, IN_object_path->file_name.field_data);
	*OUT_result = return_code == 0;
}

void filesystem_PI_get_file_size(
    const asn1SccLITTLE_FS_REPOSITORY_PATH *IN_file_path,
    asn1SccLITTLE_FS_MEMORY_OFFSET *OUT_size,
    asn1SccLITTLE_FS_BOOLEAN *OUT_result)
{
    struct lfs_info file_info;
    int return_code = lfs_stat(&lfs, IN_file_path->field_data, &file_info);
    if(return_code < 0) {
        *OUT_result = false;
        return;
    }
    if(file_info.type != LFS_TYPE_REG) {
        *OUT_result = false;
        return;
    }
    *OUT_size = file_info.size;
    *OUT_result = true;
}

void filesystem_PI_read_file(
    const asn1SccLITTLE_FS_REPOSITORY_PATH *IN_file_path,
    const asn1SccLITTLE_FS_MEMORY_OFFSET *IN_offset,
    const asn1SccLITTLE_FS_MEMORY_OFFSET *IN_length,
    asn1SccLITTLE_FS_MEMORY_DATA *OUT_content, asn1SccLITTLE_FS_BOOLEAN *OUT_result)
{
	lfs_file_t file;
	int offset = *IN_offset;
	int length = *IN_length;

	uint8_t buffer[cfg.cache_size];
	memset(buffer, 0, cfg.cache_size);

	struct lfs_attr file_attrs;
	struct lfs_file_config file_config = {
	    .buffer = buffer, .attrs = &file_attrs, .attr_count = 0};

	int return_code = lfs_file_opencfg(
	    &lfs, &file, IN_file_path->field_data,
	    LFS_O_RDWR | LFS_O_CREAT, &file_config);
	if (return_code < 0) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	if (offset != lfs_file_seek(&lfs, &file, offset, LFS_SEEK_SET)) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	if (length !=
	    lfs_file_read(&lfs, &file, OUT_content->field_data.arr, length)) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}
	OUT_content->field_data.nCount = length;

	return_code = lfs_file_close(&lfs, &file);
	if (return_code < 0) {
		*OUT_result = false;
		return;
	}

	*OUT_result = true;
}

void filesystem_PI_report_content_of_repository_request(
    const asn1SccLITTLE_FS_REPOSITORY_PATH *IN_repository_path)

{
	lfs_dir_t dir;
	struct lfs_info info;
	asn1SccLITTLE_FS_REPOSITORY_OBJECTS repo_objects;
	repo_objects.field_data.nCount = 0;

	int return_code =
	    lfs_dir_open(&lfs, &dir, IN_repository_path->field_data);
	if (return_code < 0) {
        lfs_dir_close(&lfs, &dir);
		FS_PRINT("[FileSystem] could not open a dir\n");
		return;
	}

	while (lfs_dir_read(&lfs, &dir, &info) > 0 &&
	       repo_objects.field_data.nCount <
		   MAXIMUM_OBJECT_THAT_CAN_BE_REPORTED) {
		if (info.type == LFS_TYPE_DIR) {
			repo_objects.field_data
			    .arr[repo_objects.field_data.nCount]
			    .object_type = asn1SccLITTLE_FS_OBJECT_TYPE_directory;
		} else if (info.type == LFS_TYPE_REG) {
			repo_objects.field_data
			    .arr[repo_objects.field_data.nCount]
			    .object_type = asn1SccLITTLE_FS_OBJECT_TYPE_file;
		}
		strncpy(
		    repo_objects.field_data.arr[repo_objects.field_data.nCount]
			.object_name.field_data,
		    info.name,
		    asn1SccLITTLE_FS_OBJECT_NAME_REQUIRED_BYTES_FOR_ENCODING + 1);
		repo_objects.field_data.arr[repo_objects.field_data.nCount]
		    .object_name.field_data
			[asn1SccLITTLE_FS_OBJECT_NAME_REQUIRED_BYTES_FOR_ENCODING] =
		    '\0';
		repo_objects.field_data.nCount++;
	}

	lfs_dir_close(&lfs, &dir);
	filesystem_RI_report_content_of_repository_request_respond(
	    IN_repository_path, &repo_objects);
}

void filesystem_PI_write_to_file(
    const asn1SccLITTLE_FS_REPOSITORY_PATH *IN_file_path,
    const asn1SccLITTLE_FS_MEMORY_OFFSET *IN_offset,
    const asn1SccLITTLE_FS_MEMORY_DATA *IN_content,
    asn1SccLITTLE_FS_BOOLEAN *OUT_result)

{
	lfs_file_t file;
	int offset = *IN_offset;
	int length = IN_content->field_data.nCount;

	uint8_t buffer[cfg.cache_size];
	memset(buffer, 0, cfg.cache_size);

	struct lfs_attr file_attrs;
	struct lfs_file_config file_config = {
	    .buffer = buffer, .attrs = &file_attrs, .attr_count = 0};

	int return_code = lfs_file_opencfg(
	    &lfs, &file, IN_file_path->field_data,
	    LFS_O_RDWR | LFS_O_CREAT, &file_config);
	if (return_code < 0) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	if (offset != lfs_file_seek(&lfs, &file, offset, LFS_SEEK_SET)) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	if (length !=
	    lfs_file_write(&lfs, &file, IN_content->field_data.arr, length)) {
        lfs_file_close(&lfs, &file);
		*OUT_result = false;
		return;
	}

	return_code = lfs_file_close(&lfs, &file);
	if (return_code < 0) {
		*OUT_result = false;
		return;
	}

	*OUT_result = true;
}

int block_device_read(const struct lfs_config *config, lfs_block_t block,
		      lfs_off_t off, void *buffer, lfs_size_t size)
{
	const asn1SccMEMORY_BLOCK_INDEX block_index = block;
	const asn1SccMEMORY_OFFSET block_offset = off;
	asn1SccMEMORY_DATA data;
	const asn1SccMEMORY_SIZE data_size = size;
	asn1SccT_Int32 return_code;

	memset(data.arr, 0, asn1SccMEMORY_DATA_REQUIRED_BYTES_FOR_ENCODING - 1);
	data.nCount = size;

	filesystem_RI_memory_read(&block_index, &block_offset, &data,
				  &data_size, &return_code);

	memcpy(buffer, data.arr, size);

	return return_code;
}

int block_device_prog(const struct lfs_config *c, lfs_block_t block,
		      lfs_off_t off, const void *buffer, lfs_size_t size)
{
	const asn1SccMEMORY_BLOCK_INDEX block_index = block;
	const asn1SccMEMORY_OFFSET block_offset = off;
	asn1SccMEMORY_DATA data;
	const asn1SccMEMORY_SIZE data_size = size;
	asn1SccT_Int32 return_code;

	memcpy(data.arr, buffer, size);
	data.nCount = size;

	filesystem_RI_memory_program(&block_index, &block_offset, &data,
				     &data_size, &return_code);

	return return_code;
}

int block_device_erase(const struct lfs_config *c, lfs_block_t block)
{
	const asn1SccMEMORY_BLOCK_INDEX block_index = block;
	asn1SccT_Int32 return_code;

	filesystem_RI_memory_erase(&block_index, &return_code);

	return return_code;
}

int block_device_sync(const struct lfs_config *c)
{
	asn1SccT_Int32 return_code;

	filesystem_RI_memory_sync(&return_code);

	return return_code;
}
